import{_ as o,o as t,c as a,ag as n}from"./chunks/framework.B7PviQjB.js";const i="/docs/images/board/stickies-plus-handles.png",s="/docs/images/board/stickies-connector-label.png",m=JSON.parse('{"title":"Add stickies, shapes, and connectors","description":"Add sticky notes, shapes, text boxes, images, and connectors to a board, then style and arrange them.","frontmatter":{"title":"Add stickies, shapes, and connectors","description":"Add sticky notes, shapes, text boxes, images, and connectors to a board, then style and arrange them.","type":"how-to"},"headers":[],"relativePath":"board/stickies-shapes-connectors.md","filePath":"board/stickies-shapes-connectors.md"}'),r={name:"board/stickies-shapes-connectors.md"};function l(c,e,d,h,g,p){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="add-stickies-shapes-and-connectors" tabindex="-1">Add stickies, shapes, and connectors <a class="header-anchor" href="#add-stickies-shapes-and-connectors" aria-label="Permalink to &quot;Add stickies, shapes, and connectors&quot;">​</a></h1><p>Add sticky notes, shapes, text boxes, images, and connectors to a board, then style and arrange them.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need <strong>Editor</strong> access. A viewer link can&#39;t change the board.</li><li>Images: PNG, JPEG, GIF, or WebP, up to 10 MB each.</li><li>Single-key tools such as <code>S</code> and <code>T</code> work only when nothing is selected. With an item selected, typing a letter edits that item.</li></ul></div><h2 id="add-a-sticky-note" tabindex="-1">Add a sticky note <a class="header-anchor" href="#add-a-sticky-note" aria-label="Permalink to &quot;Add a sticky note&quot;">​</a></h2><ol><li>Open the board and click empty canvas so nothing is selected.</li><li>Press <code>S</code>, or click <strong>Sticky note</strong> in the tool dock. A yellow sticky note appears in the middle of the screen, ready for typing.</li><li>Type your text. The text shrinks to fit the note.</li><li>Press <code>Escape</code> to finish.</li></ol><p>To pick another color first, click the arrow next to <strong>Sticky note</strong> and pick a color. To add a sticky note at a specific spot, right-click there and select <strong>Insert sticky note</strong>.</p><h2 id="add-the-next-sticky-note-quickly" tabindex="-1">Add the next sticky note quickly <a class="header-anchor" href="#add-the-next-sticky-note-quickly" aria-label="Permalink to &quot;Add the next sticky note quickly&quot;">​</a></h2><ul><li><strong>While typing</strong>: press <code>Tab</code> or <code>⌘+Enter</code> / <code>Ctrl+Enter</code>. The note is saved, and a new one opens to its right in the same color, size, and text size.</li><li><strong>With one sticky note selected</strong>: press <code>⌘+Enter</code> / <code>Ctrl+Enter</code>, or click one of the <strong>+</strong> handles on its four sides to add a note in that direction.</li></ul><p><img src="'+i+'" alt="A selected green sticky note with + handles at its sides and the sticky controls in the top toolbar"></p><h2 id="turn-a-pasted-list-into-sticky-notes" tabindex="-1">Turn a pasted list into sticky notes <a class="header-anchor" href="#turn-a-pasted-list-into-sticky-notes" aria-label="Permalink to &quot;Turn a pasted list into sticky notes&quot;">​</a></h2><ol><li>Copy a list of lines, or a range of cells from a spreadsheet.</li><li>Click empty canvas on the board and press <code>⌘+V</code> / <code>Ctrl+V</code>.</li></ol><p>Each line becomes one sticky note, laid out in a grid. Copied cells keep their rows and columns. One paste creates up to 100 notes.</p><h2 id="change-color-size-and-text-size" tabindex="-1">Change color, size, and text size <a class="header-anchor" href="#change-color-size-and-text-size" aria-label="Permalink to &quot;Change color, size, and text size&quot;">​</a></h2><ol><li>Select one or more sticky notes.</li><li>In the top toolbar, pick one of the six colors: Yellow, Green, Blue, Pink, Orange, or Purple.</li><li>To resize, open the size menu (<strong>Sticky size</strong>) and select <strong>Small</strong>, <strong>Medium</strong>, <strong>Large</strong>, or <strong>Wide</strong>.</li><li>To change the text size, click <strong>Decrease text size</strong> (−) or <strong>Increase text size</strong> (+).</li></ol><p>You can also drag a corner handle. A square note stays square.</p><h3 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h3><p>The six colors fold into one swatch menu in the top toolbar. Tap it to pick a color.</p><h2 id="show-or-hide-who-wrote-a-sticky-note" tabindex="-1">Show or hide who wrote a sticky note <a class="header-anchor" href="#show-or-hide-who-wrote-a-sticky-note" aria-label="Permalink to &quot;Show or hide who wrote a sticky note&quot;">​</a></h2><p>Each new sticky note records your name. To show it at the bottom of a note, select the note and click <strong>Show author</strong> (the person icon) in the top toolbar. Click it again to hide the name.</p><p>To hide every name on the board, for an anonymous brainstorm, right-click empty canvas and select <strong>Hide sticky authors</strong>. This applies for everyone on the board until someone turns it off.</p><h2 id="add-a-shape" tabindex="-1">Add a shape <a class="header-anchor" href="#add-a-shape" aria-label="Permalink to &quot;Add a shape&quot;">​</a></h2><ol><li>Click empty canvas so nothing is selected.</li><li>Click <strong>Shape</strong> in the tool dock and pick a shape: Rectangle, Rounded rectangle, Ellipse, Diamond, Triangle, Parallelogram, Arrow, Double arrow, Star, Speech bubble, Cylinder, or Hexagon. For the full catalog, click <strong>More shapes…</strong>.</li><li>Click the canvas to place the shape, or drag to set its size.</li></ol><p>Press <code>R</code> for a rectangle or <code>O</code> for an ellipse. To type in a shape, double-click it.</p><h2 id="add-a-text-box" tabindex="-1">Add a text box <a class="header-anchor" href="#add-a-text-box" aria-label="Permalink to &quot;Add a text box&quot;">​</a></h2><ol><li>Press <code>T</code>, or click <strong>Text box</strong> in the tool dock.</li><li>Click the canvas, or drag to set the width, and type.</li></ol><h2 id="add-an-image" tabindex="-1">Add an image <a class="header-anchor" href="#add-an-image" aria-label="Permalink to &quot;Add an image&quot;">​</a></h2><ul><li>Click <strong>Insert image</strong> in the tool dock and choose a file. The image lands in the middle of the screen.</li><li>Or paste an image, or drag an image file onto the board.</li></ul><p>To crop, select the image and click <strong>Crop image</strong> in the top toolbar. <strong>Reset crop</strong> restores the full image. To replace an image, delete it and insert a new one.</p><h2 id="connect-items" tabindex="-1">Connect items <a class="header-anchor" href="#connect-items" aria-label="Permalink to &quot;Connect items&quot;">​</a></h2><ol><li>Click <strong>Line</strong> in the tool dock and pick <strong>Line</strong>, <strong>Arrow</strong>, <strong>Connector</strong> (right-angle), or <strong>Curved</strong>. Or press <code>L</code> for a line, <code>Shift+L</code> for an arrow, or <code>X</code> for a connector.</li><li>Drag from one item to another. Each end attaches to the shape you drop it on.</li></ol><p>An attached end follows its shape when the shape moves. To add a label, double-click the connector and type.</p><p><img src="'+s+'" alt="Two sticky notes joined by an arrow with the label &quot;blocks&quot; in the middle"></p><h2 id="edit-text-on-an-item" tabindex="-1">Edit text on an item <a class="header-anchor" href="#edit-text-on-an-item" aria-label="Permalink to &quot;Edit text on an item&quot;">​</a></h2><ol><li>Double-click a sticky note, shape, text box, or connector. Or select it and press <code>Enter</code> or <code>F2</code>.</li><li>Use the top toolbar for font, size, bold, italic, underline, text color, alignment, and lists.</li><li>Click <strong>Done</strong> or press <code>Escape</code> when you finish.</li></ol><h2 id="change-fill-and-border" tabindex="-1">Change fill and border <a class="header-anchor" href="#change-fill-and-border" aria-label="Permalink to &quot;Change fill and border&quot;">​</a></h2><p>Select a shape, text box, or connector. In the top toolbar, use <strong>Fill color</strong> for a solid color or a gradient, and the border controls for line color, weight, and dash. A connector has no fill.</p><h2 id="arrange-items" tabindex="-1">Arrange items <a class="header-anchor" href="#arrange-items" aria-label="Permalink to &quot;Arrange items&quot;">​</a></h2><ol><li>Select the items. Drag across empty canvas to select several, or <code>Shift</code>-click each one.</li><li>Click <strong>Arrange</strong> in the top toolbar.</li><li>Select an option: <ul><li><strong>Group</strong> or <strong>Ungroup</strong></li><li><strong>Order</strong>: bring to front or forward, send backward or to back</li><li><strong>Align</strong>: needs two or more items</li><li><strong>Distribute</strong>: needs three or more items</li><li><strong>Tidy up</strong>: lines up the selection in an even grid (<code>Option+Shift+T</code> / <code>Alt+Shift+T</code>)</li><li><strong>Rotate 90° clockwise</strong> or <strong>Rotate 90° counter-clockwise</strong></li></ul></li></ol><p>Press arrow keys to nudge a selection 1 pixel, or hold <code>Shift</code> for 10 pixels.</p><h3 id="on-a-phone-1" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone-1" aria-label="Permalink to &quot;On a phone&quot;">​</a></h3><p><strong>Arrange</strong> moves to the start of the top toolbar while something is selected. Touch and hold an item to open its menu.</p><h2 id="select-similar-items" tabindex="-1">Select similar items <a class="header-anchor" href="#select-similar-items" aria-label="Permalink to &quot;Select similar items&quot;">​</a></h2><p>Right-click an item and select <strong>Select all with same colour</strong>, <strong>Select all stickies</strong>, or <strong>Select all of this type</strong>. Then restyle or move them together.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>A board has no tables.</li><li>Freehand drawing uses the marker, not the <strong>Line</strong> menu. See <a href="/docs/board/draw.html">Draw</a>.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/board/sections.html">Sections</a> to group sticky notes under a title.</li><li><a href="/docs/board/draw.html">Draw</a> to sketch with the marker and highlighter.</li><li><a href="/docs/board/keyboard-shortcuts.html">Keyboard shortcuts</a> for every tool key.</li></ul>',47)])])}const u=o(r,[["render",l]]);export{m as __pageData,u as default};
